ontology.data/ontology/mapping.json:
{
  "schema_version": "1.0",
  "status": "proposed",
  "note": "Maps record kinds, link relations and record fields to RDF. Fields with a scheme hold concept keys from data/vocab/<scheme>.ttl and export as concept IRIs. An external term is used only where its meaning matches; everything else is in the rewire vocabulary. Changes to this file are reviewed like record changes.",
  "base": "https://benchmarks.rewire.it/id/",
  "vocab": "https://benchmarks.rewire.it/vocab#",
  "prefixes": {
    "rb": "https://benchmarks.rewire.it/vocab#",
    "rdf": "http://www.w3.org/1999/02/22-rdf-syntax-ns#",
    "rdfs": "http://www.w3.org/2000/01/rdf-schema#",
    "xsd": "http://www.w3.org/2001/XMLSchema#",
    "mls": "http://www.w3.org/ns/mls#",
    "dcat": "http://www.w3.org/ns/dcat#",
    "dcterms": "http://purl.org/dc/terms/",
    "schema": "https://schema.org/",
    "obo": "http://purl.obolibrary.org/obo/"
  },
  "classes": {
    "method": {
      "types": [
        "rb:Method",
        "mls:Algorithm"
      ],
      "basis": "A described procedure, independent of a trained artifact (W3C ML Schema Algorithm)."
    },
    "model": {
      "types": [
        "rb:Model"
      ],
      "basis": "A named model or model family as released. Most model records are families, which are neither executable implementations (mls:Implementation) nor trained artifacts (mls:Model), so no external class is asserted."
    },
    "configuration": {
      "types": [
        "rb:Configuration"
      ],
      "basis": "The exact setup that produced scores. Many are reported labels, paper comparators or score-threshold schemes rather than trained artifacts, so mls:Model is not asserted."
    },
    "pipeline": {
      "types": [
        "rb:Pipeline",
        "mls:Implementation"
      ],
      "basis": "A multi-stage system; its results are not results of any model it uses."
    },
    "service": {
      "types": [
        "rb:Service",
        "schema:WebAPI"
      ],
      "basis": "A hosted service with its own terms and limits."
    },
    "benchmark": {
      "types": [
        "rb:Benchmark"
      ],
      "basis": "No external class matches a benchmark suite as used here."
    },
    "task": {
      "types": [
        "rb:Task"
      ],
      "basis": "Linking to EDAM Operation needs a reviewed per-task mapping; not yet done."
    },
    "protocol": {
      "types": [
        "rb:Protocol",
        "obo:OBI_0000272"
      ],
      "basis": "OBI protocol: a plan specification of how to carry out a process."
    },
    "evaluator": {
      "types": [
        "rb:Evaluator",
        "schema:SoftwareApplication"
      ],
      "basis": "Scoring software such as AMBER, OPAL or PoseBusters; not an implementation of a machine-learning algorithm."
    },
    "dataset": {
      "types": [
        "rb:Dataset",
        "dcat:Dataset"
      ],
      "basis": "DCAT dataset."
    },
    "dataset_subset": {
      "types": [
        "rb:DatasetSubset",
        "dcat:Dataset"
      ],
      "basis": "A defined subset is itself a dataset."
    },
    "baseline": {
      "types": [
        "rb:Baseline"
      ],
      "basis": "A proposed or source-supported comparison procedure; no external class matches."
    },
    "evaluation": {
      "types": [
        "rb:Evaluation",
        "mls:Run"
      ],
      "basis": "One execution of a configuration under a protocol, as reported."
    },
    "result": {
      "types": [
        "rb:Result",
        "mls:ModelEvaluation"
      ],
      "basis": "ML Schema ModelEvaluation holds one measured value of an evaluation measure."
    },
    "source": {
      "types": [
        "rb:Source",
        "schema:CreativeWork"
      ],
      "basis": "Paper, supplement, repository file or web page. A finer schema.org type needs a reviewed per-source field."
    },
    "claim": {
      "types": [
        "rb:Claim"
      ],
      "basis": "One sourced assertion about another record; its sources via dcterms:source."
    },
    "use_case": {
      "types": [
        "rb:UseCase"
      ],
      "basis": "A research or clinical decision question with its intended users, available inputs, desired output and setting. No external class matches: IAO objective specification (IAO_0000005) and plan specification (IAO_0000104) are directives realised by processes, schema:Question is a subclass of Comment, and NCIT Use Case (C81930) is a software interaction script."
    }
  },
  "relations": {
    "system": {
      "property": "rb:testedSystem",
      "basis": "Evaluation to the configuration, model, method, pipeline or service it evaluated. Not inherited by families."
    },
    "assessment": {
      "property": "rb:testedOn",
      "basis": "Evaluation to the task, protocol or benchmark it was assessed on."
    },
    "data": {
      "property": "rb:dataset",
      "basis": "Evaluation to the dataset or dataset subset it used."
    },
    "evaluation": {
      "property": "rb:evaluation",
      "basis": "Result to its evaluation."
    },
    "original_evaluation": {
      "property": "rb:originalEvaluation",
      "basis": "A copied result to the evaluation it was copied from."
    },
    "implemented_by": {
      "property": "rb:implementedBy",
      "basis": "Baseline to the configuration, model or method that implements it."
    },
    "measured_in": {
      "property": "rb:measuredIn",
      "basis": "Baseline to an evaluation that measured it as a comparator; the values belong to that evaluation's results."
    },
    "uses_data": {
      "property": "rb:usesData",
      "basis": "Task, protocol or baseline to the data it uses."
    },
    "used_in": {
      "property": "rb:usedIn",
      "basis": "Dataset subset to the protocol that uses it."
    },
    "family": {
      "property": "rb:family",
      "basis": "Configuration or variant to its model family. Results roll up only when a claim backs the link."
    },
    "variant_of": {
      "property": "rb:variantOf",
      "basis": "Model to the model it is a variant of. Not transitive."
    },
    "configuration_of": {
      "property": "rb:configurationOf",
      "basis": "Configuration to the model, method or pipeline it configures."
    },
    "alias_of": {
      "property": "rb:aliasOf",
      "basis": "Same identity under another ID. Deliberately not owl:sameAs, which would merge results without review."
    },
    "uses_model": {
      "property": "rb:usesModel",
      "basis": "A pipeline or service depends on a model. Not transitive and not a subproperty of rb:evaluatedSubject: pipeline results are never results of the model."
    },
    "part_of": {
      "property": "rb:partOf",
      "basis": "Component of a suite. A subproperty of dcterms:isPartOf and of the transitive rb:within, so the transitivity applies only to rewire part-of links."
    },
    "parent": {
      "property": "rb:parent",
      "basis": "Hierarchy within a benchmark."
    },
    "evaluates_task": {
      "property": "rb:evaluatesTask",
      "basis": "Resource to the task it evaluates."
    },
    "applicable_to": {
      "property": "rb:applicableTo",
      "basis": "Candidate applicability; not evidence of performance."
    },
    "same_data_as": {
      "property": "rb:sameDataAs",
      "basis": "Informational data reuse; never merges results."
    },
    "companion_of": {
      "property": "rb:companionOf",
      "basis": "Source to the paper it belongs with: its repository, leaderboard, supplement or another version of the paper. The discrepancy rules treat both as one study (docs/discrepancies.md). Never merges results."
    },
    "assessed_by": {
      "property": "rb:assessedBy",
      "basis": "Use case to a protocol that a relevance judgement claim grades for it. Every asserted link is exported, including those whose judgement is still a draft; the claim's status and grade decide whether its evaluations count as evidence. Not a subproperty of rb:testedOn and in no property chain, so no result is inferred to belong to a use case. No external property starts from a question: the domain of SEPIO has_evidence (SEPIO_0000189) is a proposition or assertion, and oa:hasTarget starts from an annotation."
    },
    "supersedes": {
      "property": "dcterms:replaces",
      "basis": "A newer record replacing an older one."
    },
    "subject": {
      "property": "rb:subject",
      "basis": "Claim to the record it is about."
    },
    "source": {
      "property": "dcterms:source",
      "basis": "Record to a source it is derived from."
    }
  },
  "fields": {
    "name": {
      "property": "rdfs:label"
    },
    "description": {
      "property": "dcterms:description"
    },
    "status": {
      "property": "rb:status",
      "scheme": "status"
    },
    "source_ids": {
      "property": "dcterms:source",
      "iri": true,
      "basis": "The source the record (a description) is taken from. prov:wasDerivedFrom would make every described thing, including evaluation runs, a prov:Entity derived from a paper."
    }
  },
  "facets": {
    "areas": {
      "property": "rb:area",
      "scheme": "area"
    },
    "tasks": {
      "property": "rb:taskFacet"
    },
    "contexts": {
      "property": "rb:context",
      "scheme": "context"
    },
    "method_types": {
      "property": "rb:methodType",
      "scheme": "method-type"
    }
  },
  "attributes": {
    "version": {
      "property": "schema:version"
    },
    "entity_level": {
      "property": "rb:entityLevel",
      "scheme": "entity-level"
    },
    "url": {
      "property": "schema:url",
      "iri": true
    },
    "doi": {
      "property": "rb:doi"
    },
    "retrieved_at": {
      "property": "rb:retrievedAt",
      "datatype": "xsd:dateTime"
    },
    "artifact_sha256": {
      "property": "rb:artifactSha256"
    },
    "publication_status": {
      "property": "rb:publicationStatus",
      "scheme": "publication-status"
    },
    "origin": {
      "property": "rb:origin",
      "scheme": "origin"
    },
    "metric": {
      "property": "rb:metric",
      "scheme": "metric"
    },
    "metric_direction": {
      "property": "rb:metricDirection",
      "scheme": "direction"
    },
    "unit": {
      "property": "rb:unit",
      "scheme": "unit"
    },
    "printed_value": {
      "property": "rb:printedValue"
    },
    "numeric_value": {
      "property": "mls:hasValue",
      "datatype": "xsd:decimal"
    },
    "uncertainty": {
      "property": "rb:uncertainty"
    },
    "source_locator": {
      "property": "rb:sourceLocator"
    },
    "field": {
      "property": "rb:claimField"
    },
    "split": {
      "property": "rb:split"
    },
    "method_type": {
      "property": "rb:methodType",
      "scheme": "method-type"
    },
    "baseline_type": {
      "property": "rb:baselineType",
      "scheme": "baseline-type"
    },
    "configuration_type": {
      "property": "rb:configurationType",
      "scheme": "configuration-type"
    },
    "unit_detail": {
